mapper.select:
select * from ( select o.id, g.id glueGroupId, g.glue_group_code, g.glue_group_name, o.glue_code, o.order_num, concat(g.order_num,'.',o.order_num) as glue_group_order_num, o.remark from T_TC_GLUE_GROUP_ORDER g inner join T_TC_GLUE_ORDER o on g.id = o.glue_group_id where 1=1 and g.del_flag=0 and o.del_flag=0
and GLUE_GROUP_ID = #{glueGroupId}
and INSTR(GLUE_CODE, #{glueCode}) > 0
order by g.order_num, o.order_num
) t
order by ${orderStr}
